<script>
  import { onMount } from 'svelte';
  import WindowControls from './WindowControls.svelte';
  import { reminderWindow, visibleReminders, reminderDate, reminderEpoch, reminderColors, reminderDateValid } from './reminders-state.js';
  import { remindersMenuProvider } from './reminders-commands.js';
  import { createRemindersNativeView } from './reminders-native-view.js';
  import './reminders.css';
  let { state: remindersData, profile, windowId, execute, registerView, available = true, active = true, controls = {} } = $props();
  let root, mounted = false, originalRoot, originalState;
  let error = $state(''), menu = $state(''), listDraft = $state(null), accountDraft = $state(null), shareText = $state(''), sheetKey = $state(''), dragging = $state(null);
  const windows = $derived(profile.id.includes('windows'));
  const classic = $derived(profile.id.includes('high-sierra') || profile.id.includes('mojave'));
  const golden = $derived(profile.id.includes('golden-gate'));
  const era = $derived(windows ? 'windows' : profile.id.includes('high-sierra') ? 'high-sierra' : profile.id.includes('mojave') ? 'mojave' : golden ? 'golden' : 'sonoma');
  const win = $derived(reminderWindow(remindersData, windowId));
  const sceneTime = $derived(reminderEpoch(controls.sceneTime ?? profile.defaults.sceneTime));
  const today = $derived(reminderDate(sceneTime));
  const tasks = $derived(visibleReminders(remindersData, windowId, sceneTime));
  const selected = $derived(remindersData.tasks.find(row => row.id === win?.selectedId));
  const list = $derived(remindersData.lists.find(row => row.id === win?.listId));
  const editor = $derived(win?.editor);
  const menus = $derived(remindersMenuProvider(remindersData, windowId, profile));
  const title = $derived(win?.query ? 'Search Results' : win?.view === 'list' ? list?.name ?? (windows ? 'Tasks' : 'Reminders') : win?.view === 'my-day' ? 'My Day' : win?.view === 'scheduled' && windows ? 'Planned' : win?.view === 'flagged' && windows ? 'Important' : win?.view?.charAt(0).toUpperCase() + win?.view?.slice(1));
  const smartViews = $derived(classic ? [['scheduled','◷','Scheduled']] : windows ? [['my-day','☀','My Day'],['flagged','☆','Important'],['scheduled','▦','Planned'],['all','☷','Tasks'],['completed','✓','Completed']] : [['today','▣','Today'],['scheduled','▦','Scheduled'],['all','▤','All'],['flagged','⚑','Flagged'],['completed','✓','Completed']]);
  function owns() { return mounted && available && remindersData === originalState && root === originalRoot && root?.isConnected && !root.closest('[hidden],[inert]'); }
  async function command(name, payload = {}) {
    if (!owns()) return null;
    const saved = root, previousSheet = win?.sheet;
    try { const result = await execute(`reminders.${name}`, { windowId }, payload); if (owns() && saved === root) { error = result?.status === 'rejected' ? result.error?.message ?? 'This operation is unavailable.' : ''; if (result?.status === 'applied' && win?.sheet !== previousSheet) root.querySelector('.reminders-sheet input, .reminders-sheet textarea, .reminders-sheet button, .reminders-sheet select')?.focus({preventScroll:true}); } return result; }
    catch (cause) { if (owns()) error = cause?.message ?? 'This operation is unavailable.'; return null; }
  }
  const field = (key, value) => command('editor.set', { spec: { ...editor, [key]: value } });
  function setDue(date, time, hasTime = classic ? true : editor.hasTime) { const dueAt = date && reminderDateValid(date) ? Date.parse(`${date}T${hasTime ? time || '09:00' : '00:00'}:00Z`) : null; const recurrence = dueAt === null ? null : editor.recurrence && editor.recurrence.until !== null && editor.recurrence.until < dueAt ? { ...editor.recurrence, until: null } : editor.recurrence; command('editor.set', { spec: { ...editor, dueAt, hasTime: dueAt !== null && hasTime, recurrence } }); }
  const dueDate = $derived(editor?.dueAt !== null && editor?.dueAt !== undefined ? reminderDate(editor.dueAt) : '');
  const dueTime = $derived(editor?.dueAt !== null && editor?.dueAt !== undefined ? new Date(editor.dueAt).toISOString().slice(11,16) : '09:00');
  function recurrence(value) { field('recurrence', value === 'none' ? null : { frequency: value, interval: 1, until: null }); }
  function count(view) { const enabled = new Set(remindersData.lists.filter(list => remindersData.accounts.find(row=>row.id===list.accountId)?.enabled).map(row=>row.id)); return remindersData.tasks.filter(row => enabled.has(row.listId) && (view==='completed' ? row.completed : !row.completed) && (view === 'scheduled' ? row.dueAt !== null : view === 'today' ? row.dueAt !== null && reminderDate(row.dueAt) <= today : view === 'flagged' ? row.flagged : view === 'my-day' ? row.myDay === today : true)).length; }
  const dateText = task => task.dueAt === null ? '' : `${reminderDate(task.dueAt) === today ? 'Today' : reminderDate(task.dueAt)}${task.hasTime ? ', ' + new Date(task.dueAt).toISOString().slice(11,16) : ''}`;
  function monthDays(date) { const current = new Date(`${date}T00:00:00Z`), y = current.getUTCFullYear(), m = current.getUTCMonth(), start = new Date(Date.UTC(y,m,1)), length = new Date(Date.UTC(y,m+1,0)).getUTCDate(); return [...Array(start.getUTCDay()).fill(null), ...Array.from({length}, (_,i) => reminderDate(Date.UTC(y,m,i+1)))]; }
  const calendarDays = $derived(win ? monthDays(win.calendarDate) : []);
  function shiftMonth(direction) { const date = new Date(`${win.calendarDate}T00:00:00Z`); date.setUTCDate(1); date.setUTCMonth(date.getUTCMonth()+direction); command('view.set',{calendarDate:reminderDate(date.getTime())}); }
  async function openSheet(sheet, id) { sheetKey = ''; await command('sheet.open',{sheet,...(id ? {listId:id} : {})}); }
  async function menuAction(item) { menu = ''; if (!item.enabled) return; try { const result = await execute(item.command,item.target,item.payload); if (owns()) error = result?.status === 'rejected' ? result.error.message : ''; } catch (cause) { if (owns()) error = cause.message; } }
  function keydown(event) {
    if (!owns()) return;
    if (event.key === 'Tab' && win?.sheet !== 'none') {
      const sheet = root.querySelector('.reminders-sheet'), nodes = sheet ? [...sheet.querySelectorAll('input,textarea,select,button,[tabindex="0"]')].filter(node=>!node.disabled&&!node.closest('[hidden],[inert]')) : [];
      if (nodes.length && (event.shiftKey && event.target === nodes[0] || !event.shiftKey && event.target === nodes.at(-1) || !sheet.contains(event.target))) { event.preventDefault(); (event.shiftKey ? nodes.at(-1) : nodes[0]).focus(); }
    }
    if (event.key === 'Escape') { event.preventDefault(); menu = ''; if (win.editor) command('editor.cancel'); else if (win.sheet !== 'none') command('sheet.close'); return; }
    if ((windows ? event.ctrlKey : event.metaKey) && !event.altKey) {
      const key = event.key.toLowerCase(), action = key === 'n' ? event.shiftKey ? ['sheet.open',{sheet:'list'}] : ['task.new',{}] : key === 'f' ? ['focus',{controlId:'search'}] : key === ',' ? ['sheet.open',{sheet:'preferences'}] : key === 'w' ? ['window.close',{}] : key === 'z' ? [event.shiftKey?'edit.redo':'edit.undo',{}] : key === 'c' ? ['edit.copy',{}] : key === 'x' ? ['edit.cut',{}] : key === 'v' ? ['edit.paste',{}] : key === 'a' ? ['edit.selectAll',{}] : null;
      if (action) { event.preventDefault(); event.stopPropagation(); command(action[0],action[1]); }
    } else if (event.key === 'Delete' && selected && !['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName) && !win.editor) { event.preventDefault(); command('task.delete',{reminderId:selected.id}); }
  }
  $effect(() => {
    const key = `${win?.sheet}:${win?.editingListId ?? ''}`; if (key === sheetKey) return; sheetKey = key;
    if (win?.sheet === 'list') { const row = remindersData.lists.find(row => row.id === win.editingListId); listDraft = row ? {id:row.id,accountId:row.accountId,name:row.name,color:row.color} : {id:null,accountId:remindersData.accounts.find(row=>row.enabled)?.id ?? '',name:'New List',color:reminderColors[0]}; }
    if (win?.sheet === 'accounts') accountDraft = {id:null,name:'Local account',provider:windows?'Microsoft':'iCloud',enabled:true};
    if (win?.sheet === 'share') shareText = remindersData.lists.find(row=>row.id === (win.editingListId ?? win.listId))?.sharedWith.join('\n') ?? '';
  });
  onMount(() => { mounted = true; originalRoot = root; originalState = remindersData; const view = createRemindersNativeView({root,owns}); registerView(windowId,view); return () => { mounted = false; registerView(windowId,null,view); }; });
</script>

<div bind:this={root} class="reminders-app era-{era}" class:inactive={!active} class:dark={remindersData.preferences.theme === 'dark'} style:--list-color={list?.color ?? '#6558ce'} data-reminders-window={windowId} role="application" tabindex="-1" onkeydown={keydown}>
  <header class="reminders-chrome" data-window-drag>
    {#if !windows}<WindowControls {...controls} {active} /><span class="caption">{classic ? 'Reminders' : ''}</span>{:else}<span class="caption">Microsoft To Do</span>{/if}
    <div class="reminders-menus" data-window-no-drag>
      {#each menus as group}<div class="menu-wrap"><button data-reminder-control="menu:{group.id}" aria-haspopup="menu" aria-expanded={menu === group.id} onclick={() => menu = menu === group.id ? '' : group.id}>{group.label}</button>{#if menu === group.id}<div class="menu-popup" role="menu">{#each group.items as item}<button role="menuitem" disabled={!item.enabled} onclick={() => menuAction(item)}><span>{item.label}</span><kbd>{windows ? item.shortcut.replaceAll('⌘','Ctrl+') : item.shortcut}</kbd></button>{/each}</div>{/if}</div>{/each}
    </div>
  </header>
  <div class="reminders-layout">
    {#if win?.sidebar}<aside class="reminders-sidebar">
      {#if windows}<div class="todo-account"><span class="avatar">JD</span><div><strong>Local Microsoft account</strong><small>Fictional · no synchronization</small></div><button aria-label="Accounts" onclick={() => openSheet('accounts')}>⌄</button></div>{/if}
      {#if !golden}<label class="reminder-search"><span>⌕</span><input data-reminder-control="search" aria-label="Search reminders" placeholder={windows ? 'Search' : 'Search'} value={win.query} oninput={event => command('view.set',{query:event.currentTarget.value})} /></label>{/if}
      <div class="smart-lists">{#each smartViews as [view,icon,label]}<button class:selected={win.view === view} class="smart-{view}" data-reminder-control="view:{view}" onclick={() => command('view.set',{view,query:''})}><span class="smart-icon">{icon}</span><strong>{count(view)}</strong><span class="smart-label">{label}</span></button>{/each}</div>
      <div class="account-lists">{#each remindersData.accounts as account}<section class:disabled-account={!account.enabled}><h3>{account.name}</h3>{#each remindersData.lists.filter(row => row.accountId === account.id) as row}<button class:selected={win.view === 'list' && win.listId === row.id} disabled={!account.enabled} data-reminder-control="list:{row.id}" draggable="true" ondragstart={event => { dragging={kind:'list',id:row.id}; event.dataTransfer.setData('text/plain',row.id); }} ondragover={event=>event.preventDefault()} ondrop={event=>{event.preventDefault(); if(dragging?.kind==='task') command('task.move',{reminderId:dragging.id,listId:row.id}); else if(dragging?.kind==='list') command('list.reorder',{listId:dragging.id,index:remindersData.lists.indexOf(row)}); dragging=null;}} onclick={() => command('view.set',{view:'list',listId:row.id,query:''})}><span class="list-badge" style:background-color={row.color}>☷</span><span>{row.name}</span>{#if row.sharedWith.length}<span aria-label="Shared locally">♙</span>{/if}{#if !classic}<small>{remindersData.tasks.filter(task=>task.listId===row.id&&!task.completed).length}</small>{/if}</button>{/each}</section>{/each}</div>
      {#if win.calendar}<div class="mini-calendar"><div><button aria-label="Previous month" onclick={()=>shiftMonth(-1)}>‹</button><strong>{win.calendarDate.slice(0,7)}</strong><button aria-label="Next month" onclick={()=>shiftMonth(1)}>›</button></div><div class="calendar-grid">{#each ['S','M','T','W','T','F','S'] as day}<small>{day}</small>{/each}{#each calendarDays as date}{#if date}<button class:today={date===today} class:selected={date===win.calendarDate} data-reminder-control="date:{date}" ondragover={event=>event.preventDefault()} ondrop={event=>{event.preventDefault();if(dragging?.kind==='task')command('calendar.assign',{reminderId:dragging.id,date});dragging=null;}} onclick={()=>{command('view.set',{calendarDate:date});if(selected)command('calendar.assign',{reminderId:selected.id,date});}}>{Number(date.slice(-2))}</button>{:else}<span></span>{/if}{/each}</div><small>Drop a reminder on a date · 9:00 UTC</small></div>{/if}
      <button class="add-list" data-reminder-control="add-list" onclick={()=>openSheet('list')}>⊕ {windows ? 'New list' : 'Add List'}</button>
    </aside>{/if}
    <main class="reminders-main">
      {#if golden}<div class="golden-tools"><button aria-label="Toggle sidebar" onclick={()=>command('view.set',{sidebar:!win.sidebar})}>▥</button><button aria-label="Share list" disabled={!list} onclick={()=>openSheet('share',list.id)}>♙</button><button aria-label="List info" disabled={!list} onclick={()=>openSheet('list',list.id)}>☷</button><button data-reminder-control="new" aria-label="Add reminder" onclick={()=>command('task.new')}>＋</button><label class="reminder-search"><span>⌕</span><input data-reminder-control="search" aria-label="Search reminders" placeholder="Search" value={win.query} oninput={event=>command('view.set',{query:event.currentTarget.value})}/></label></div>{/if}
      <div class="list-heading"><h1>{title}</h1>{#if !classic}<strong class="list-count">{tasks.filter(row=>!row.completed).length}</strong>{/if}<button class="new-reminder" data-reminder-control="new-reminder" aria-label="Add reminder" onclick={()=>command('task.new')}>＋</button>{#if windows}<button aria-label="List settings" onclick={()=>openSheet('list',list?.id)}>···</button>{/if}</div>
      <div class="completion-line"><span>{remindersData.tasks.filter(row=>row.completed&&(win.view!=='list'||row.listId===win.listId)).length} Completed</span><button data-reminder-control="completed-toggle" onclick={()=>command('view.set',{showCompleted:!win.showCompleted})}>{win.showCompleted?'Hide':'Show'}</button></div>
      <div class="reminder-rows" data-reminder-scroll>
        {#each tasks as task (task.id)}<article class="reminder-row" class:selected={task.id===win.selectedId} class:completed={task.completed} draggable="true" ondragstart={event=>{dragging={kind:'task',id:task.id};event.dataTransfer.setData('text/plain',task.id);}} ondragover={event=>event.preventDefault()} ondrop={event=>{event.preventDefault();if(dragging?.kind==='task')command('task.move',{reminderId:dragging.id,listId:task.listId,index:remindersData.tasks.filter(row=>row.listId===task.listId).findIndex(row=>row.id===task.id)});dragging=null;}}>
          <button class="completion-circle" class:checked={task.completed} data-reminder-control="complete:{task.id}" aria-label={task.completed ? `Mark ${task.title} incomplete` : `Complete ${task.title}`} aria-pressed={task.completed} onclick={()=>command('task.setCompleted',{reminderId:task.id,completed:!task.completed})}>{task.completed?'✓':''}</button>
          <button class="task-content" data-reminder-control="task:{task.id}" onclick={()=>command(windows?'task.edit':'task.select',{reminderId:task.id})} ondblclick={()=>{if(!windows)command('task.edit',{reminderId:task.id});}}><span class="task-title">{#if task.priority}<b class="priority">{'!'.repeat(task.priority)}</b>{/if}{task.title}</span>{#if task.notes}<small class="task-notes">{task.notes}</small>{/if}<small class:overdue={task.dueAt!==null&&task.dueAt<sceneTime&&!task.completed}>{dateText(task)}{task.recurrence ? ', ' + task.recurrence.frequency : ''}{task.location ? ' · ' + task.location.label + ' (fictional)' : ''}{win.view!=='list'?' · '+(remindersData.lists.find(row=>row.id===task.listId)?.name??''):''}</small></button>
          {#if windows}<button class="star" aria-label={task.flagged?'Remove importance':'Mark important'} onclick={()=>command('task.flag',{reminderId:task.id,flagged:!task.flagged})}>{task.flagged?'★':'☆'}</button>{:else if task.flagged}<span class="flag">⚑</span>{/if}<button class="info" data-reminder-control="info:{task.id}" aria-label={`Details for ${task.title}`} onclick={()=>command('task.edit',{reminderId:task.id})}>ⓘ</button>
        </article>{/each}
        {#if tasks.length===0}<p class="empty-list">{win.query?'No reminders found':windows?'Add a task to get started':'No Reminders'}</p>{/if}
        <button class="inline-add" data-reminder-control="inline-add" onclick={()=>command('task.new')}><span>＋</span>{windows?'Add a task':'New Reminder'}</button>
      </div>
      {#if selected}<footer class="selection-actions"><button onclick={()=>command('task.edit',{reminderId:selected.id})}>Details</button><label>Move to <select aria-label="Move selected reminder" value={selected.listId} onchange={event=>command('task.move',{reminderId:selected.id,listId:event.currentTarget.value})}>{#each remindersData.lists as row}<option value={row.id}>{row.name}</option>{/each}</select></label><button aria-label="Move reminder up" onclick={()=>command('task.reorder',{reminderId:selected.id,index:Math.max(0,remindersData.tasks.filter(row=>row.listId===selected.listId).findIndex(row=>row.id===selected.id)-1)})}>↑</button><button aria-label="Move reminder down" onclick={()=>command('task.reorder',{reminderId:selected.id,index:remindersData.tasks.filter(row=>row.listId===selected.listId).findIndex(row=>row.id===selected.id)+1})}>↓</button><button disabled={selected.dueAt===null} onclick={()=>command('calendar.open',{reminderId:selected.id})}>Calendar</button><button onclick={()=>command('task.delete',{reminderId:selected.id})}>Delete</button></footer>{/if}
      <div class="alert-ledger"><button data-reminder-control="process-alerts" onclick={()=>command('alerts.process')}>Process authored-time alerts</button>{#each remindersData.alerts.filter(row=>['delivered','snoozed'].includes(row.status)) as alert}<div class="alert-row"><span>{remindersData.tasks.find(task=>task.id===alert.reminderId)?.title} · {alert.status}{alert.snoozeAt ? ' until '+new Date(alert.snoozeAt).toISOString().slice(0,16).replace('T',' ')+' UTC':''}</span><button onclick={()=>command('alert.snooze',{alertId:alert.id,minutes:5})}>5 min</button><button onclick={()=>command('alert.snooze',{alertId:alert.id,minutes:60})}>1 hour</button><button onclick={()=>command('alert.complete',{alertId:alert.id})}>Complete</button><button onclick={()=>command('alert.dismiss',{alertId:alert.id})}>Dismiss</button></div>{/each}</div>
    </main>
  </div>
  {#if error}<div class="reminders-error" role="alert">{error}<button aria-label="Dismiss error" onclick={()=>error=''}>×</button></div>{/if}
  {#if win?.sheet!=='none'}<div class="reminders-sheet-backdrop"><section class="reminders-sheet sheet-{win?.sheet}" role="dialog" aria-modal="true" aria-label={win.sheet==='inspector'?(windows?'Task details':'Reminder info'):win.sheet}>
    {#if win.sheet==='inspector' && editor}
      <header><h2>{windows?'Task details':'Info'}</h2><button aria-label="Cancel inspector" onclick={()=>command('editor.cancel')}>×</button></header>
      <label class="editor-title">{windows?'Task':'Reminder'}<input data-reminder-control="title" value={editor.title} oninput={event=>field('title',event.currentTarget.value)} maxlength="1024" /></label>
      <label>Notes<textarea data-reminder-control="notes" value={editor.notes} oninput={event=>field('notes',event.currentTarget.value)} maxlength="65536" placeholder="Add notes"></textarea></label>
      <label>List<select value={editor.listId} onchange={event=>field('listId',event.currentTarget.value)}>{#each remindersData.lists as row}<option value={row.id}>{row.name}</option>{/each}</select></label>
      <fieldset><legend>{windows?'Due date and reminder':'Remind me'}</legend><label class="check"><input type="checkbox" checked={editor.dueAt!==null} onchange={event=>setDue(event.currentTarget.checked?today:'',dueTime)}/>{windows?'Add due date':'On a Day'}</label>{#if editor.dueAt!==null}<div class="date-fields"><input aria-label="Due date" type="date" value={dueDate} onchange={event=>setDue(event.currentTarget.value,dueTime)}/>{#if !classic}<label class="check"><input type="checkbox" checked={editor.hasTime} onchange={event=>setDue(dueDate,dueTime,event.currentTarget.checked)}/>{windows?'Remind me':'At a Time'}</label>{/if}{#if editor.hasTime || classic}<input aria-label="Due time UTC" type="time" value={dueTime} onchange={event=>setDue(dueDate,event.currentTarget.value)}/>{/if}</div><small>Authored scene time · UTC; no host clock</small>
      <label>Repeat<select value={editor.recurrence?.frequency??'none'} onchange={event=>recurrence(event.currentTarget.value)}><option value="none">None</option>{#each ['daily','weekly','monthly','yearly'] as frequency}<option value={frequency}>{frequency.charAt(0).toUpperCase()+frequency.slice(1)}</option>{/each}</select></label>{#if editor.recurrence}<label>Every <input type="number" min="1" max="365" value={editor.recurrence.interval} onchange={event=>field('recurrence',{...editor.recurrence,interval:Number(event.currentTarget.value)})}/> interval(s)</label><label>End repeat<input aria-label="End repeat date" type="date" value={editor.recurrence.until===null?'':reminderDate(editor.recurrence.until)} onchange={event=>field('recurrence',{...editor.recurrence,until:event.currentTarget.value?Date.parse(`${event.currentTarget.value}T23:59:59Z`):null})}/></label>{/if}{/if}</fieldset>
      <fieldset><legend>{windows?'Local extension · fictional location':'At a Location · fictional'}</legend><label class="check"><input type="checkbox" checked={editor.location!==null} onchange={event=>field('location',event.currentTarget.checked?{label:'Trailhead',transition:'arriving',radius:100}:null)}/>Enable fictional location trigger</label>{#if editor.location}<label>Location<input value={editor.location.label} oninput={event=>field('location',{...editor.location,label:event.currentTarget.value})}/></label><div class="date-fields"><label class="check"><input type="radio" name="transition-{windowId}" checked={editor.location.transition==='arriving'} onchange={()=>field('location',{...editor.location,transition:'arriving'})}/>Arriving</label><label class="check"><input type="radio" name="transition-{windowId}" checked={editor.location.transition==='leaving'} onchange={()=>field('location',{...editor.location,transition:'leaving'})}/>Leaving</label></div><label>Radius: {editor.location.radius} m<input type="range" min="50" max="10000" step="50" value={editor.location.radius} oninput={event=>field('location',{...editor.location,radius:Number(event.currentTarget.value)})}/></label><div class="fictional-map"><span class="location-radius"></span><span class="location-pin">●</span><small>{editor.location.label} · fictional map, no geolocation</small></div>{#if win.editorId}<button onclick={()=>command('location.trigger',{reminderId:win.editorId,transition:editor.location.transition})}>Simulate saved {editor.location.transition} trigger</button>{/if}{/if}</fieldset>
      <label>{windows?'Local extension · priority':'Priority'}<select value={editor.priority} onchange={event=>field('priority',Number(event.currentTarget.value))}><option value="0">None</option><option value="1">Low !</option><option value="2">Medium !!</option><option value="3">High !!!</option></select></label><label class="check"><input type="checkbox" checked={editor.flagged} onchange={event=>field('flagged',event.currentTarget.checked)}/>{windows?'Important':'Flagged'}</label>{#if windows}<label class="check"><input type="checkbox" checked={editor.myDay===today} onchange={event=>field('myDay',event.currentTarget.checked?today:null)}/>Add to My Day</label>{/if}
      <footer><button onclick={()=>command('editor.cancel')}>Cancel</button><button class="primary" data-reminder-control="save" onclick={()=>command('editor.save')}>Done</button></footer>
    {:else if win.sheet==='list' && listDraft}<header><h2>{listDraft.id?'List Info':'New List'}</h2></header><label>Name<input data-reminder-control="list-name" bind:value={listDraft.name}/></label><label>Account<select bind:value={listDraft.accountId}>{#each remindersData.accounts.filter(row=>row.enabled) as row}<option value={row.id}>{row.name}</option>{/each}</select></label><div class="list-colors">{#each reminderColors as color}<button class:selected={listDraft.color===color} style:background={color} aria-label={color} onclick={()=>listDraft.color=color}></button>{/each}</div><footer><button onclick={()=>command('sheet.close')}>Cancel</button><button class="primary" onclick={()=>command('list.save',{...(listDraft.id?{listId:listDraft.id}:{}),accountId:listDraft.accountId,name:listDraft.name,color:listDraft.color})}>Done</button></footer>
    {:else if win.sheet==='delete-list' || win.sheet==='delete-task'}<h2>Delete {win.sheet==='delete-list'?'List':'Reminder'}?</h2><p>{win.sheet==='delete-list'?'The list and every reminder in it will be permanently deleted from this fictional account.':'This reminder will be permanently deleted.'}</p><footer><button onclick={()=>command('sheet.close')}>Cancel</button><button class="danger" onclick={()=>win.sheet==='delete-list'?command('list.delete',{listId:win.editingListId,confirmed:true}):command('task.delete',{reminderId:win.selectedId,confirmed:true})}>Delete</button></footer>
    {:else if win.sheet==='preferences'}<h2>{windows?'Settings':classic?'Preferences':'Settings'}</h2><label>Default List<select value={remindersData.preferences.defaultListId??''} onchange={event=>command('preferences.set',{preferences:{...remindersData.preferences,defaultListId:event.currentTarget.value||null}})}><option value="">None</option>{#each remindersData.lists as row}<option value={row.id}>{row.name}</option>{/each}</select></label>{#each [['showCompleted','Show completed in new windows'],['notifications','Deliver authored-time notifications'],['confirmDelete','Confirm reminder deletion'],['ascending','Ascending sort order']] as [key,label]}<label class="check"><input type="checkbox" checked={remindersData.preferences[key]} onchange={event=>command('preferences.set',{preferences:{...remindersData.preferences,[key]:event.currentTarget.checked}})}/>{label}</label>{/each}<label>Sort<select value={remindersData.preferences.sort} onchange={event=>command('preferences.set',{preferences:{...remindersData.preferences,sort:event.currentTarget.value}})}>{#each ['manual','due','priority','title'] as value}<option>{value}</option>{/each}</select></label><label>All-day reminder hour (UTC)<input type="number" min="0" max="23" value={remindersData.preferences.allDayHour} onchange={event=>command('preferences.set',{preferences:{...remindersData.preferences,allDayHour:Number(event.currentTarget.value)}})}/></label><label>Theme<select value={remindersData.preferences.theme} onchange={event=>command('preferences.set',{preferences:{...remindersData.preferences,theme:event.currentTarget.value}})}>{#each ['system','light','dark'] as value}<option>{value}</option>{/each}</select></label><small>{windows?'Priority levels, fictional locations and Calendar are local extensions to Microsoft To Do.':'Local scene preferences; no real account or Location Services changes.'}</small><footer><button class="primary" onclick={()=>command('sheet.close')}>Done</button></footer>
    {:else if win.sheet==='accounts' && accountDraft}<h2>Accounts</h2><p>Fictional accounts · local records only, no sign-in or transport.</p><div class="accounts-table">{#each remindersData.accounts as row}<div><button onclick={()=>accountDraft={id:row.id,name:row.name,provider:row.provider,enabled:row.enabled}}>{row.name} ({row.provider})</button><label class="check"><input type="checkbox" checked={row.enabled} onchange={event=>command('account.save',{accountId:row.id,name:row.name,provider:row.provider,enabled:event.currentTarget.checked})}/>Enabled</label><button onclick={()=>{accountDraft={id:row.id,name:row.name,provider:row.provider,enabled:row.enabled};}}>Edit</button></div>{/each}</div><label>Name<input bind:value={accountDraft.name}/></label><label>Provider<select bind:value={accountDraft.provider}>{#each ['local','iCloud','Exchange','Microsoft','Yahoo','AOL'] as value}<option>{value}</option>{/each}</select></label><button onclick={()=>command('account.save',{...(accountDraft.id?{accountId:accountDraft.id}:{}),name:accountDraft.name,provider:accountDraft.provider,enabled:accountDraft.enabled})}>Save account</button><button onclick={()=>accountDraft={id:null,name:'Local account',provider:windows?'Microsoft':'iCloud',enabled:true}}>New account</button>{#if accountDraft.id}<label class="check"><input type="checkbox" id="delete-account-confirm-{windowId}"/>I understand all lists in this account will be deleted</label><button class="danger" onclick={()=>command('account.delete',{accountId:accountDraft.id,confirmed:root.querySelector(`#delete-account-confirm-${windowId}`)?.checked===true})}>Delete account</button>{/if}<footer><button class="primary" onclick={()=>command('sheet.close')}>Done</button></footer>
    {:else if win.sheet==='share'}<h2>Share List</h2><p>Fictional sharing. Names are local presentation; no invitation is sent.</p><label>Members (one per line)<textarea bind:value={shareText}></textarea></label><footer><button onclick={()=>command('sheet.close')}>Cancel</button><button class="primary" onclick={()=>command('list.share',{listId:win.editingListId??win.listId,members:shareText.split('\n').map(value=>value.trim()).filter(Boolean)})}>Done</button></footer>
    {:else if win.sheet==='about'}<h2>{windows?'Microsoft To Do':'Reminders'}</h2><p>Fictional native-era workspace for {profile.id}.</p><p>One canonical local task graph. No live synchronization, real notifications, account authentication or geolocation outside this scene.</p><footer><button onclick={()=>command('sheet.close')}>Done</button></footer>
    {:else if win.sheet==='help'}<h2>{windows?'To Do':'Reminders'} Help</h2><p>Create a list, then add reminders. Double-click a reminder or choose Info to edit its notes, priority, due date, recurrence and fictional location.</p><p>Drag reminders between lists or into the sidebar calendar; use the arrows to reorder. Search includes titles and notes. Completion of a recurring reminder advances the same canonical ID to its next due date.</p><p>Authored-time alerts are processed only using the scene clock. Snooze dismisses the current shared notification and reserves a future authored-time delivery. Calendar opens the actual due day, without copying the reminder into an event.</p><p>{classic?'Today/All/Flagged shortcuts and Preferences are explicitly local additions where not present in the historical application.':windows?'Priority levels, fictional locations, accounts and Calendar bridge are explicitly local extensions to To Do.':'Fictional location simulation and accounts do not contact live services.'}</p><footer><button onclick={()=>command('sheet.close')}>Done</button></footer>{/if}
  </section></div>{/if}
</div>
